//串口指令
void get() {
		uint8_t index;
		fre = 0;
		va=0;
		for (int i = 0; i < 10; i++) 
		{
				if(frev[i]==0x01)
				{
					index=i;
					break;
				}
		}
		for (int i = 1; i < index; i++) 
		{
				fre = fre * 10 + (frev[i] - '0');
		}
		va=(float)(frev[index+1]- '0')*1.0f+(float)(frev[index+3]- '0')/10.0f;
 
}

void get2() 
{
    uint8_t index = 0xFF;  // 初始为非法值
    fre2 = 0;              // fre2 清零

    for (int i = 0; i < 8; i++) 
    {
        if (frev2[i] == 0xFF) 
        {
            index = i;
            break;
        }
    }

    if (index != 0xFF)  // 找到0xFF
    {
        for (int i = 0; i < index; i++) 
        {
            fre2 = fre2 * 10 + (frev2[i] - '0');
        }
    }
    else
    {
        // 错误处理：没有找到0xFF
        fre2 = 0;
    }
}

void detect_filter(uint16_t size)
{
    float threshold = 0.707f;  // -3dB点
//    uint16_t rise_cut = 0, fall_cut = 0;
//    uint8_t cut_count = 0;

    // 找到拐点
    for (uint16_t i = 2; i < size; i++)
    {
			 if(Fre_v[i]>Fre_v[maxindex])
			 {
				 maxindex=i;
			 }
			 if(Fre_v[i]<Fre_v[minindex])
			 {
				 minindex=i;
			 }
        if (Fre_v[i - 1] >= threshold && Fre_v[i] < threshold)
        {
            fall_cut = i;
            cut_count++;
        }
        if (Fre_v[i - 1] <= threshold && Fre_v[i] > threshold)
        {
            rise_cut = i;
            cut_count++;
        }
    }

    if (cut_count == 2)
    {
        // 检查rise_cut和fall_cut之间是否一直高于threshold
        uint8_t is_bandpass = 1;
			if(rise_cut<fall_cut)
			{
        for (uint16_t i = rise_cut + 1; i < fall_cut; i++)
        {
            if (Fre_v[i] < threshold)
            {
                is_bandpass = 0;
                break;
            }
        }
			}
			else
			{
				is_bandpass = 0;
				for (uint16_t i = fall_cut + 1; i < rise_cut; i++)
        {
            if (Fre_v[i] > threshold)
            {
                is_bandpass = 1;
                break;
            }
        }
			}
        if (is_bandpass)
        {
            tjc_send_txt("t5", "txt", "band pass");
        }
        else
        {
            tjc_send_txt("t5", "txt", "band stop");
        }
    }
    else if (cut_count == 1)
    {
        if (rise_cut == 0)
        {
            tjc_send_txt("t5", "txt", "low pass");
        }
        else if (fall_cut == 0)
        {
            tjc_send_txt("t5", "txt", "high pass");
        }
    }
    else
    {
			if((maxindex-minindex)>4000&&maxindex>minindex)
			{
				tjc_send_txt("t5", "txt", "high pass");
			}
			else
				tjc_send_txt("t5", "txt", "Unknown");
    }
}

//单位 Khz
void Set_SampleRate(TIM_TypeDef *timer, uint32_t target_freq) {
    uint32_t timer_clk = 240000;  // 240MHz
    uint32_t psc;
//		__HAL_TIM_DISABLE(&htim4);  // 可选，防止CNT正好在边界

		__HAL_TIM_SET_COUNTER(&htim4, 0);  // CNT清零（可选，看需求）
    if (target_freq == 0) return;  // 防止除0错误

    // 计算ARR重装数
    psc = (timer_clk / target_freq) - 1;

    // 限制ARR合法范围 (16位定时器最大65535)
    if (psc > 0xFFFF) psc = 0xFFFF;
		TIM4->ARR=psc;


//		TIM4->EGR = TIM_EGR_UG;  // 触发更新事件，让ARR和PSC立即生效

//		__HAL_TIM_ENABLE(&htim4);  // 可选，重新启用
}


void dftphase(int fre)
{
	float s1;
	float c1;
	float s1q;
	float c1q;
	float v1,v1q;
	uint16_t fc1=2500;
	uint16_t f1=0;
	s1=0;
	c1=0;
	s1q=0;
	c1q=0;
	float p1,p1q;
	 for (int i=0;i<10000;i++)   
    {
        s1+=(float)AD_value[i]*si_10000[f1];
        c1+=(float)AD_value[i]*si_10000[fc1];
			  s1q+=(float)AD_value2[i]*si_10000[f1];
        c1q+=(float)AD_value2[i]*si_10000[fc1];
        f1+=fre;
				fc1+=fre;
        if (f1>=10000)
        {
            f1-=10000;
        }       
        if (fc1>=10000)
        {
            fc1-=10000;
        }
		}
//	s1/=2500.0f;
//	c1/=2500.0f;
//	s1q/=2500.0f;
//	c1q/=2500.0f;
		v1q=s1q*s1q+c1q*c1q;
		Fre_c[fre]=(c1*c1q+s1*s1q)/v1q;
		Fre_s[fre]=(s1q*c1-s1*c1q)/v1q;
		Fre_v[fre]=sqrtf(Fre_c[fre]*Fre_c[fre]+Fre_s[fre]*Fre_s[fre]);
//		Fre_v[fre]=sqrtf(Fre_c[fre]*Fre_c[fre]*v1q+Fre_s[fre]*Fre_s[fre]*v1q);
}

//扫频，幅频特性
