									HAL_TIM_Base_Start(&htim6);
									HAL_DAC_Start_DMA(&hdac1,DAC_CHANNEL_2,(uint32_t*)DA_value,10000,DAC_ALIGN_12B_R);
								while(!(halflag&&comflag));
